@import "@fontsource-variable/figtree";
@import "@fontsource-variable/inter";
@import "@fontsource-variable/jetbrains-mono";

/* Light (sibling): a pale lavender page #f7f5ff, indigo ink #140f33 with 62% ink for secondary
   text, ink-10% hairlines, a deep violet button that keeps its lilac rim, the same #6d5cff
   emphasis violet and a soft lilac glow. */
:root {
  --background: #f7f5ff;
  --foreground: #140f33;
  --card: #fdfcff;
  --card-foreground: #140f33;
  --popover: #ffffff;
  --popover-foreground: #140f33;
  --primary: #2a1670;
  --primary-foreground: #f7f5ff;
  --secondary: #ece8fb;
  --secondary-foreground: #140f33;
  --muted: #e7e2f8;
  --muted-foreground: rgb(20 15 51 / 62%);
  --accent: #e3ddf8;
  --accent-foreground: #140f33;
  --destructive: #d9365a;
  --destructive-foreground: #ffffff;
  --border: rgb(20 15 51 / 10%);
  --input: rgb(20 15 51 / 14%);
  --ring: rgb(109 92 255 / 55%);
  --highlight: #6d5cff;
  --highlight-foreground: #ffffff;
  --glow: #8f73ff;
  --chart-1: #6d5cff;
  --chart-2: #c45ee8;
  --chart-3: #8c63f0;
  --chart-4: #5c78e8;
  --chart-5: #5046e4;
  --sidebar: #fdfcff;
  --sidebar-foreground: #140f33;
  --sidebar-primary: #2a1670;
  --sidebar-primary-foreground: #f7f5ff;
  --sidebar-accent: #ece8fb;
  --sidebar-accent-foreground: #140f33;
  --sidebar-border: rgb(20 15 51 / 10%);
  --sidebar-ring: rgb(109 92 255 / 55%);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Figtree Variable", "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "JetBrains Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* buttons and small chrome: 8px; cards use rounded-2xl (16px) */
  --radius: 0.5rem;
  /* the 1200px content frame */
  --page-width: 75rem;
  /* 20px on phones, up to 32px on tablets */
  --page-gutter: clamp(1.25rem, 0.9rem + 1.4vw, 2rem);
  /* ~88px between sections on phones, ~120px at 1440 */
  --section-y: clamp(5.5rem, 4.6rem + 2.4vw, 7.5rem);
}

/* Dark (faithful): the near-black indigo page #030014, lavender-white ink #f4f0ff with
   lavender-60% secondary text, lavender-8% hairlines, deep violet #1d0c46 buttons, #9382ff
   for mentions and active states, violet #7b5cff light. */
.dark {
  --background: #030014;
  --foreground: #f4f0ff;
  --card: #0a0721;
  --card-foreground: #f4f0ff;
  --popover: #0e0a28;
  --popover-foreground: #f4f0ff;
  --primary: #1d0c46;
  --primary-foreground: #ffffff;
  --secondary: #0f0c24;
  --secondary-foreground: #ffffff;
  --muted: #13102c;
  --muted-foreground: rgb(239 237 253 / 60%);
  --accent: #16132f;
  --accent-foreground: #f4f0ff;
  --destructive: #ff5c7a;
  --destructive-foreground: #030014;
  --border: rgb(243 238 255 / 9%);
  --input: rgb(243 238 255 / 10%);
  --ring: rgb(147 130 255 / 60%);
  --highlight: #9382ff;
  --highlight-foreground: #030014;
  --glow: #7b5cff;
  --chart-1: #9382ff;
  --chart-2: #e59cff;
  --chart-3: #ba9cff;
  --chart-4: #9cb2ff;
  --chart-5: #5046e4;
  --sidebar: #0a0721;
  --sidebar-foreground: #f4f0ff;
  --sidebar-primary: #5046e4;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #16132f;
  --sidebar-accent-foreground: #f4f0ff;
  --sidebar-border: rgb(243 238 255 / 9%);
  --sidebar-ring: rgb(147 130 255 / 60%);
}
